export interface SceneNodeViewModel {
  id: string;
  label: string;
  subtitle?: string;
  href?: string;
  q: number;
  r: number;
  variant?: string;
  size?: string;
  active?: boolean;
  selected?: boolean;
  disabled?: boolean;
}

export interface SceneEdgeViewModel {
  from: string;
  to: string;
  active?: boolean;
  muted?: boolean;
  fromSocket?: string;
  toSocket?: string;
}

export interface LabSectionViewModel {
  id: string;
  eyebrow: string;
  title: string;
  summary: string;
  details: string[];
  meta: string[];
  location: string;
}

type PagesEntry = CollectionEntry<"pages">;

