function parseConnectionRef(input: string) {
  return input.includes(":") ? input.split(":").slice(1).join(":") : input;
}

function toKnowledgeEntity(entry: PagesEntry): KnowledgeEntityInput {
  const data = entry.data;
  return {
    id: data.id,
    type: data.type,
    title: data.title,
    subtitle: data.subtitle,
    summary: data.summary,
    description: data.description,
    body: entry.body,
    tags: data.tags,
    q: data.q,
    r: data.r,
    language: data.language,
    metadata: {
      href: data.href,
      variant: data.variant,
      size: data.size,
      active: data.active,
      selected: data.selected,
      disabled: data.disabled,
      eyebrow: data.eyebrow,
      summary: data.summary,
      details: data.details,
      meta: data.meta,
    },
  };
}

function toKnowledgeRelationships(entry: PagesEntry): KnowledgeRelationshipInput[] {
  const sourceId = entry.data.id;
  return (entry.data.connections ?? []).map((connection) => ({
    from: sourceId,
    to: parseConnectionRef(connection),
    active: entry.data.active,
    muted: !entry.data.active,
  }));
}

async function loadRepository() {
  const pages = await getCollection("pages");
  return new KnowledgeRepository({
    entities: pages.map(toKnowledgeEntity),
    relationships: pages.flatMap(toKnowledgeRelationships),
  });
}

async function getRepository() {
  repositoryPromise ??= loadRepository();
  return repositoryPromise;
}

function toSceneNode(entity: KnowledgeEntityRecord): SceneNodeViewModel {
  const metadata = entity.metadata as Record<string, unknown>;
  return {
    id: entity.id,
    label: entity.label,
    subtitle: entity.subtitle,
    href: typeof metadata.href === "string" ? metadata.href : undefined,
    q: entity.q ?? 0,
    r: entity.r ?? 0,
    variant: typeof metadata.variant === "string" ? metadata.variant : undefined,
    size: typeof metadata.size === "string" ? metadata.size : undefined,
    active: Boolean(metadata.active),
    selected: Boolean(metadata.selected),
    disabled: Boolean(metadata.disabled),
  };
}

function toLabSection(entity: KnowledgeEntityRecord): LabSectionViewModel {
  const metadata = entity.metadata as Record<string, unknown>;
  return {
    id: entity.id,
    eyebrow: typeof metadata.eyebrow === "string" ? metadata.eyebrow : "Node",
    title: entity.title,
    summary: typeof metadata.summary === "string" ? metadata.summary : "",
    details: Array.isArray(metadata.details) ? metadata.details.filter((detail): detail is string => typeof detail === "string") : [],
    meta: Array.isArray(metadata.meta) ? metadata.meta.filter((item): item is string => typeof item === "string") : [],
    location: typeof entity.q === "number" && typeof entity.r === "number" ? String(entity.q) + ", " + String(entity.r) : "",
  };
}

function buildEdges(repository: KnowledgeRepository, ids: string[], metaMap: Record<string, { active?: boolean; muted?: boolean; fromSocket: string; toSocket: string }>) {
  const allowed = new Set(ids);
  return repository.getAllRelationships()
    .filter((relationship) => allowed.has(relationship.from) && allowed.has(relationship.to))
    .map((relationship) => {
      const key = relationship.from + "->" + relationship.to;
      const meta = metaMap[key] ?? { fromSocket: "s", toSocket: "n" };
      return {
        from: relationship.from,
        to: relationship.to,
        active: meta.active ?? relationship.active,
        muted: meta.muted ?? relationship.muted,
        fromSocket: meta.fromSocket,
        toSocket: meta.toSocket,
      } satisfies SceneEdgeViewModel;
    });
}

function pickNodes(repository: KnowledgeRepository, ids: string[]) {
  return ids
    .map((id) => repository.getEntity(id))
    .filter((entity): entity is KnowledgeEntityRecord => Boolean(entity))
    .map(toSceneNode);
}

function pickSections(repository: KnowledgeRepository, ids: string[]) {
  return ids
    .map((id) => repository.getEntity(id))
    .filter((entity): entity is KnowledgeEntityRecord => Boolean(entity))
    .map(toLabSection);
}

function createHomePresetNodes() {
  return HOME_PRESET_DEFINITIONS.map((preset) => ({
    id: preset.id,
    label: preset.label,
    subtitle: preset.subtitle,
    href: `#${preset.targetId}`,
    q: preset.q,
    r: preset.r,
    variant: preset.variant,
    size: preset.size,
    active: preset.id === "homepage-opening",
    selected: preset.id === "homepage-opening",
    disabled: preset.id !== "homepage-opening",
  }));
}

function createHomePresetSections() {
  return HOME_PRESET_DEFINITIONS.map((preset) => ({
    id: preset.targetId,
    presetId: preset.id,
    label: preset.label,
    subtitle: preset.subtitle,
    summary: preset.id === "homepage-opening"
      ? "Canonical opening scene for the site: reveal the topology, establish orientation, and hand off into the main world."
      : `${preset.label} composes the site around ${preset.subtitle.toLowerCase()}.`,
  }));
}

export async function createHomeSceneData() {
  const repository = await getRepository();
  const nodes = createHomePresetNodes();
  const edges = Object.entries(HOME_EDGE_META).map(([key, meta]) => {
    const [from, to] = key.split("->");
    return {
      from,
      to,
      active: meta.active,
      muted: meta.muted,
      fromSocket: meta.fromSocket,
      toSocket: meta.toSocket,
    } satisfies SceneEdgeViewModel;
  });

  return {
    repository,
    presets: createHomePresetSections(),
    nodes,
    edges,
  };
}

export async function createLabSceneData() {
  const repository = await getRepository();
  return {
    repository,
    nodes: pickNodes(repository, LAB_NODE_IDS),
    edges: buildEdges(repository, LAB_NODE_IDS, LAB_EDGE_META),
    sections: pickSections(repository, LAB_SECTION_IDS),
  };
}
